package org.pag.domain

enum class MemoryAnswerType { BOOLEAN_UNCERTAIN, SINGLE_CHOICE, MULTI_CHOICE, SHORT_TEXT, LONG_TEXT, APPROX_DURATION, APPROX_TIME, OPTIONAL_COUNT }
data class MemorySection(val ordinal: Int, val key: String, val title: String)
data class MemoryOption(val key: String, val label: String)
class MemoryDependency(val parentKey: String, acceptedOptions: Set<String>, val contextHint: String? = null) {
    val acceptedOptions: Set<String> = java.util.Collections.unmodifiableSet(acceptedOptions.toSet())
    fun active(answers: Map<String, MemoryAnswerValue>): Boolean = when (val value = answers[parentKey]) {
        is MemoryAnswerValue.Option -> value.key in acceptedOptions
        is MemoryAnswerValue.Multi -> value.keys.any { it in acceptedOptions }
        else -> false
    }
}
class MemoryQuestion(val key: String, val sectionOrdinal: Int, val order: Int, val type: MemoryAnswerType,
    val text: String, val hint: String, options: List<MemoryOption>, val dependency: MemoryDependency?,
    val limit: Int, val contractText: String) {
    val options: List<MemoryOption> = java.util.Collections.unmodifiableList(options.toList())
}
